<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import Icon from '@/Components/UI/Icon.vue'; import HrNav from '../Partials/HrNav.vue'; import HrPageHeader from '../Partials/HrPageHeader.vue'; import AttendanceForm from './AttendanceForm.vue';
defineOptions({layout:AppLayout}); const props=defineProps({record:Object,employees:[Array,Object]}); const local=(value)=>value?value.slice(0,16):''; const form=useForm({employee_uuid:props.record.employee.uuid,started_at:local(props.record.started_at),ended_at:local(props.record.ended_at),observation:props.record.observation??''}); const submit=()=>form.put(`/administration/attendance/${props.record.uuid}`);
</script>
<template><Head title="Corriger une présence"/><div class="space-y-5"><HrNav/><HrPageHeader :eyebrow="`${record.employee.employee_number} · Correction auditée`" title="Corriger la session" :description="`Session de ${record.employee.name}. La date de travail sera recalculée depuis l’heure d’entrée.`" icon="edit" tone="violet"><template #actions><Link href="/administration/attendance" class="inline-flex h-10 items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 text-sm font-bold text-slate-600 hover:border-violet-300 hover:text-violet-600 dark:border-gray-800 dark:bg-gray-950 dark:text-slate-200"><Icon name="arrow-left"/> Retour aux présences</Link></template></HrPageHeader><AttendanceForm :form="form" :employees="employees" cancel-href="/administration/attendance" submit-label="Enregistrer la correction" @submit="submit"/></div></template>
